import type { StoryChoice, WrittenStory } from './storyTypes';

const c = (label: string, hint: string, icon: StoryChoice['icon']): StoryChoice => ({ label, hint, icon });

export const storiesA: Record<string, WrittenStory> = {
  weather: {
    threadLabel: 'Help Mopperwolk het juiste weer naar het dorpsfeest te brengen.',
    scenes: (picks, hero) => [
      {
        title: 'Een winkel vol weer',
        text: `Boven een groen heuveltje klingelt een bel. ${hero} ontdekt een winkel met regen in flessen, wind in doosjes en zonneschijn onder een theemuts. Achter de toonbank staat Mopperwolk. Zijn ronde bril is beslagen. ‘O, goed dat je komt! Het dorp bestelde picknickweer. Maar mijn etiketten zijn losgewaaid.’ In een potje rommelt iets. Uit een ander steekt een piepkleine regenboog. Buiten de deur wacht een lege bezorgkar. Mopperwolk wil graag helpen, maar hij durft de potten niet zomaar open te maken. Op de vloer liggen de etiketten. De potjes lijken ondertussen zachtjes tegen elkaar te praten.\n\nMopperwolk trekt een laatje open. Er liggen een zachte doek, een vergrootglas en een stapel lege kaartjes in. ‘Mijn winkel was vanochtend nog keurig,’ vertelt hij. ‘Toen kwam de tocht binnen om een sjaal te kopen. Hij blies van blijdschap zo hard dat alle briefjes gingen vliegen.’ Bij die herinnering schudt een potje op de plank alsof het moet giechelen. Jij schuift het voorzichtig verder van de rand.\n\nOp de toonbank staat een foto van het dorpsplein. Er staan lange tafels op, met slingers tussen de bomen. Een klein muisje heeft op de achterkant een broodje getekend. Het feest begint straks, maar er is tijd om goed te kijken. Mopperwolk zet zijn bril recht en legt de doek klaar. ‘Zeg het maar. Ik help jou, en jij helpt mij.’\n\nWaar begin je?`,
        choices: [c('Sorteer de etiketten', 'Zoek bij elke tekening het juiste potje.', 'compass'), c('Luister naar de potjes', 'Misschien vertelt het weer zelf wat het is.', 'music')],
      },
      {
        title: 'De kar met de slappe wielen',
        text: `${picks[0] === 0 ? 'Je houdt een zonnetekening tegen het warme potje. Het past! De andere etiketten vinden ook hun plek.' : 'Het ritselende potje blijkt wind. Het tikkende potje bevat regen. De zonneschijn zingt een heel hoog liedje.'} Mopperwolk poetst blij zijn bril. Jullie zetten alle bestellingen in de kar, met de zon rechtop tussen twee kussentjes. Alleen zakken de zachte wolkenwielen plat zodra de laatste fles erbij komt. ‘Te zwaar,’ zucht Mopperwolk. Naast de deur woont een brede huisjesslak met een sterke bezorgplank. Aan de schoorsteen wappert een lang lint vol lichte briesjes. Daarmee kan de kar misschien een stukje zweven. Bij de dorpstoren worden de eerste broodmanden al neergezet. Mopperwolk legt een doek over de bestelling, zodat alle doppen netjes blijven zitten.\n\nJij hurkt naast een wiel. Het lijkt op een kussen dat zijn lucht kwijt is. Als Mopperwolk een hoekje optilt, veert het even terug. Laat hij los, dan wordt het weer een platte pannenkoek. ‘Vanmorgen waren ze nog rond,’ moppert hij. Zijn bril glijdt naar zijn neus. Jullie moeten allebei lachen, want de kar ziet er nu uit alsof hij wil gaan slapen.\n\nDe bezorgslak steekt zijn ogen boven zijn huisje uit. Hij heeft een bordje met een getekende pijl en houdt zijn plank al een beetje vrij. Het briesjeslint aan de schoorsteen maakt juist kleine krullen in de lucht. Jullie bekijken allebei de mogelijkheden. Welke reis het ook wordt, de flessen blijven dicht en de zon blijft veilig tussen de kussens. Mopperwolk controleert iedere dop nog eens met een tevreden knikje.\n\nHoe willen jullie op weg?`,
        choices: [c('Vraag de bezorgslak', 'Rustig rollen met een sterke helper.', 'heart'), c('Leen het briesjeslint', 'Laat de kar licht boven het pad zweven.', 'sparkles')],
      },
      {
        title: 'Een bui op de verkeerde plek',
        text: `${picks[1] === 0 ? 'De slak schuift zijn plank onder de kar. Met een tevreden brommetje draagt hij de bestelling naar het dorpsplein.' : 'Mopperwolk knoopt het briesjeslint vast. De kar zweeft net boven de madeliefjes, terwijl jij hem rustig vooruit trekt.'} Op het plein staan lege picknicktafels. Boven de limonadekraam hangt een klein regenwolkje vast onder de luifel. Het was gisteren verkeerd bezorgd. ‘Ik kan nergens heen,’ drupt het. Mopperwolk houdt zijn hoed onder de druppels. De kraamhouder heeft een heerlijke rozenplant naast de deur en een zacht tikkend lepeltje op de toonbank. Misschien volgt het wolkje een geur of een ritme naar buiten. Aan de rand van het plein staan de bloemen een beetje slap. Ze kunnen die verdwaalde regen juist heel goed gebruiken.\n\nJij kijkt omhoog naar de luifel. Bij iedere druppel trekt het wolkje een verdrietig mondje. De kraamhouder zet snel een kan onder het lek. ‘Voor mijn bloemen mag het best regenen,’ zegt ze. ‘Maar regenlimonade staat vandaag niet op de kaart.’ Het wolkje moet daarvan een beetje lachen. Een druppel springt vrolijk op de rand van de kan.\n\nMopperwolk vertelt dat kleine regenwolkjes graag iets volgen dat prettig voelt. Hard duwen helpt niet: dan trekken ze zich juist samen. Je wilt het wolkje dus een uitnodiging geven. Naast de rozenstruik ligt een smal pad naar de bloembakken. Het is breed genoeg voor jullie en loopt helemaal buiten de kraam om. De kraamhouder schuift haar limonadeglazen opzij en geeft jullie de ruimte. Het wolkje houdt nieuwsgierig op met druppen om te zien wat jullie gaan bedenken.\n\nWat probeer je?`,
        choices: [c('Maak een rozengeurspoor', 'Lok het wolkje naar de dorstige bloemen.', 'leaf'), c('Tik een rustig regenritme', 'Laat het wolkje op de maat met je mee bewegen.', 'music')],
      },
      {
        title: 'Waar is de zonnespetter?',
        text: `${picks[2] === 0 ? 'De rozengeur kriebelt in het wolkje. Het zweeft achter de geur aan en geeft de bloemen precies genoeg water.' : 'Tik, tikkerdetik! Het wolkje wiegt mee met jouw lepeltje. Zo leid je het naar de bloembakken naast het plein.'} De kraamhouder zwaait opgelucht. Nu kan Mopperwolk het picknickweer uitpakken. Maar het potje zonneschijn blijft bleek. Eén gouden zonnespetter is eruit gesprongen! Op de lege parasols liggen kleine lichtvlekjes. In de verse regendruppels aan de bloemen schitteren ook gouden puntjes. Jullie hebben een doorzichtig maatbekertje en een opgevouwen, glanzende paraplu. Daarmee kun je het licht verzamelen. Mopperwolk houdt alvast het potje open. De verloren zonnespetter piept als een kuikentje. Zodra je dichterbij komt, springt het geluid weer naar een andere lichtvlek.\n\nDe paraplu heeft geen gaten om doorheen te regenen. De binnenkant lijkt op een zilveren vijver waarin de wolken weerspiegelen. Het maatbekertje heeft kleine streepjes langs de zijkant. Op het onderste streepje staat een tekening van één zonnespetter. Mopperwolk wijst er met zijn zachte vinger naar. ‘Meer hebben we helemaal niet nodig. Eén goed plekje voor dat ene lichtje.’\n\nJij ziet dat een gouden vlekje op je schoen meebeweegt wanneer je een stap zet. Het licht speelt verstoppertje, maar het vlucht niet echt. Soms blijft het even zitten om warm te worden. Op een parasol verschijnt een ronde neus van licht. Dan verdwijnen twee oogjes tussen de plooien. De kraamhouder zet de tafels alvast klaar en laat de glinsterende druppels aan de bloemen hangen. Zo heeft de zonnespetter genoeg plekjes om nog even te schitteren.`,
        choices: [c('Vang licht in de druppels', 'Gebruik het heldere maatbekertje.', 'sparkles'), c('Vouw de glansparaplu open', 'Laat de lichtvlekjes naar het potje glijden.', 'compass')],
      },
      {
        title: 'Weer om samen van te genieten',
        text: `${picks[3] === 0 ? 'De druppels bundelen hun glinstering in je bekertje. Een warme zonnespetter springt terug in het potje.' : 'Op de glansparaplu ontmoeten alle lichtvlekjes elkaar. Samen glijden ze als één zonnespetter het potje in.'} Meteen kleurt het plein goud. Mopperwolk zet wat koele schaduw naast de limonade en een klein briesje bij de slingers. De kinderen komen aan met mandjes brood. ‘Er is nog een beetje feestweer over, ${hero},’ zegt hij. In een schaal ligt een regenboog als een zacht lint. Daarnaast ligt een dekentje van kleine wolken. Jullie kunnen een kleurrijke route door het dorp maken, of een fijne picknickplek die met iedereen meebeweegt.\n\nEen jongetje zet zijn broodmand neer en merkt dat de schaduw precies naast hem meeschuift. Hij doet één stap naar links. Het donkere plekje volgt. Hij doet een stap naar rechts en moet hard lachen. Mopperwolk buigt alsof hij een bijzonder kunstje heeft gedaan. ‘Goed weer luistert een beetje naar de mensen die het gebruiken,’ zegt hij.\n\nOp het plein worden bekers verdeeld. De kraamhouder geeft jullie de eerste twee glazen limonade en houdt er één omhoog tegen het gouden licht. Er dansen zeven kleuren in. Jij bekijkt het regenbooglint en de wolkendeken. Allebei passen ze bij dit feest, alleen maken ze er iets anders van. Mopperwolk legt de materialen naast elkaar en haalt geen dop meer van een pot. Dit laatste stukje van de bestelling mogen jullie rustig zelf vormgeven, terwijl de broodjes hun heerlijke geur over het plein verspreiden.\n\nWat kies jij?`,
        choices: [c('Een regenboogroute door het dorp', 'Verbind het plein met alle kleine straatjes.', 'compass'), c('Een bijzondere picknickplek', 'Maak samen een fijne plek onder het feestweer.', 'heart')],
      },
    ],
    ending: (picks, hero) => picks[4] === 0 ? {
      title: 'Het pad met zeven kleuren',
      text: `Jullie rollen het regenbooglint uit langs de dorpsstraatjes. Bij ieder bankje hangt een klein plukje schaduw. Bij iedere bloembak valt precies één vriendelijk buitje. Mensen nemen hun broodmand mee en wandelen samen naar het plein. Mopperwolk rijdt nog één rondje om alles te bekijken. ‘Bestelling helemaal goed bezorgd!’ zegt hij. Voor ${hero} maakt hij een piepklein regenbooglint dat je kunt oprollen. Als je het weer uitrolt, denk je aan jullie tocht en de potjes die hun plek terugvonden.\n\nBij de laatste bocht houdt een oud konijn stil. Hij kijkt naar de kleuren op het pad en kiest een bankje met precies genoeg schaduw. Een paar kinderen tellen de tinten van het lint, maar halverwege raken ze de tel kwijt omdat de limonade wordt rondgebracht. Dat geeft niets; de kleuren blijven rustig liggen.\n\nMopperwolk bergt zijn bezorgdoek op. De potten zijn leeg genoeg om terug te dragen en vol genoeg om de herinnering aan het feest te bewaren. Jij voelt het kleine lintje in je hand. Het is koel aan de blauwe kant en warm aan de gele kant. Wanneer je nog eenmaal omkijkt, wijzen zeven kleuren de dorpsbewoners vriendelijk de weg.`,
      keepsake: 'Een opgerold regenbooglint',
    } : picks[0] === 0 ? {
      title: 'De wolkendeken boven het plein',
      text: `Je vouwt de wolkendeken boven de tafels open. Hij schuift rustig mee met de zon, zodat de broodjes warm blijven en niemand in zijn ogen hoeft te knijpen. De regenboog wordt een gekleurde rand om de deken. Mopperwolk hangt er zorgvuldig een nieuw etiket aan: ‘Picknickweer, met aandacht gemaakt.’ Iedereen vindt een plekje. ${hero} krijgt het kleinste wolkenlapje mee. Het voelt zo zacht als een pas opgeschud kussen en herinnert je aan de winkel vol bijzonder weer.\n\nEen klein meisje kijkt onder de rand van de deken en vraagt of een wolk ook kruimels lust. Mopperwolk denkt heel ernstig na. ‘Alleen kruimels van een regenkoek,’ zegt hij. Iedereen lacht, en de deken beweegt zacht mee alsof hij zelf ook moet giechelen.\n\nNa het eten worden de lege manden onder de tafels geschoven. Niemand hoeft direct op te staan. Er is tijd voor nog een slokje limonade, een verhaal of zomaar even kijken naar de slingers. Jij vouwt jouw wolkenlapje voorzichtig dubbel. Het wordt klein genoeg voor je zak, maar het blijft voelen als die grote zachte schaduw boven het hele plein. Mopperwolk zwaait terwijl de wolkendeken rustig met de middagzon meeschuift.`,
      keepsake: 'Een zacht lapje picknickwolk',
    } : {
      title: 'Het weer dat meewandelde',
      text: `Mopperwolk knoopt zonneschijn, schaduw en een stukje regenboog aan een lange tak. Zo ontstaat een vrolijk weermobiel. Wie met een broodmand over het plein loopt, krijgt vanzelf een fijn plekje onder de bewegende wolkjes. Jullie schuiven de tafels in een grote kring en proeven samen de limonade. ‘Deze bestelling ga ik onthouden,’ glimlacht Mopperwolk. Hij geeft ${hero} een klein zonneknoopje van het mobiel. Het glanst, ook wanneer je het in je jaszak stopt.\n\nEen broodmand blijft even midden op het plein staan. Meteen zweeft een klein schaduwplekje erboven, alsof het weermobiel begrijpt dat ook broodjes prettig koel willen blijven. De kraamhouder probeert het met een kan limonade en krijgt precies zo’n eigen wolkje. Mopperwolk bekijkt zijn werk met grote ronde ogen. Dit soort weer had hij zelf nog nooit bezorgd.\n\nLater worden de slingers stil en zakken de stemmen naar een gezellig gemurmel. Je draait het zonneknoopje tussen je vingers. Het maakt een klein gouden vlekje op je hand, zonder heet te worden. Bij de winkelbel wacht de lege bezorgkar op morgen. Vandaag kan Mopperwolk zijn bril afzetten en gewoon naast jullie van het feest genieten.`,
      keepsake: 'Een gouden zonneknoopje',
    },
    encounters: picks => picks.length ? [{ id: 'weather-mopperwolk', name: 'Mopperwolk', fact: picks[0] === 0 ? 'Je hielp Mopperwolk de losse weeretiketten te sorteren.' : 'Je ontdekte samen met Mopperwolk welk weer in de potjes zat door te luisteren.' }] : [],
  },
  moonbakery: {
    threadLabel: 'Ontdek met Mies hoe het maanbrood weer luchtig kan worden.',
    scenes: (picks, hero) => [
      {
        title: 'Een plat brood op de maan',
        text: `Wanneer ${hero} naar de maan zwaait, gaat er een rond raampje open. Een konijn met een meelneus steekt zijn kop naar buiten. ‘Ik ben Mies. Kun je even helpen?’ Een trapje van zacht maanlicht brengt je naar haar bakkerij. Hier liggen sterrenbroodjes op kussens en staat een oven met gouden voetjes. Maar het grote maanbrood is zo plat als een pannenkoek. Het moet straks de ontbijtbel laten klinken voor alle kleine maanbewoners. Mies heeft al gekneed, gewacht en haar oren gekrabd. Er ontbreekt iets. Achter op de plank staat een oud receptenblik. Vanuit het deeg klinkt een heel zacht gebrom.\n\nMies legt een schone handdoek op een kruk, zodat je prettig bij de tafel kunt zitten. Door de vloer loopt een dun streepje maanlicht. Het kringelt langzaam om de kom, maar zelfs dat maakt het deeg niet wakker. ‘Gisteren was het nog zo hoog,’ zegt Mies. Ze houdt haar oren recht omhoog om te laten zien hoe hoog. Vandaag laat ze ze slap langs haar wangen hangen.\n\nJij kijkt eens goed rond. Aan een haak hangt een zeef met stervormige gaatjes. In een glazen pot slapen rozijntjes onder een suikerdekentje. De oven knippert met zijn twee warme raampjes. Mies zorgt zelf voor het vuur; jij mag helpen onderzoeken wat het brood nodig heeft. Buiten schuift iemand alvast een ontbijtbank onder het raam. Er komt een zacht getrommel van lege lepeltjes. De maanbewoners hebben zin in iets lekkers, en jullie willen hun een heerlijk begin van de dag geven.\n\nWat onderzoek je eerst?`,
        choices: [c('Open het receptenblik', 'Misschien staat er een vergeten stap in.', 'compass'), c('Luister naar het deeg', 'Wat probeert het zachte brommetje te zeggen?', 'music')],
      },
      {
        title: 'Op zoek naar wensgist',
        text: `${picks[0] === 0 ? 'In het receptenblik vind je een kaartje met een tekening van een lichtgevend bolletje: wensgist.' : 'Je houdt je oor bij de kom. ‘Wensgist,’ bromt het deeg slaperig. ‘Een klein korreltje is al genoeg.’'} Mies klapt in haar meelpoten. Wensgist groeit bij de krater aan de overkant van het plein. Op de maan is het ochtend, dus overal rollen broodbezorgers met volle manden voorbij. Tussen hun sporen liggen platte sterstenen als een veilig wandelpad. Langs de rand van het plein stroomt een smalle rivier van melkachtig maanlicht. Mies heeft een grote houten lepel die daarin als een bootje kan drijven. Mies stopt het lege gistkommetje in haar schortzak. Voor je vertrek geeft de oven een kleine, hoopvolle zucht; hij bewaart het deeg voor jullie.\n\nMies hangt een klein briefje aan de bakkersdeur: even op zoek naar een bijzonder ingrediënt. Ze tekent er een kommetje bij, zodat iedereen begrijpt waarom de winkel kort dicht is. De oven leest het briefje door het raam en knikt heel langzaam. Het deeg blijft bij hem in de warme bakkerij, onder een schone doek.\n\nOp het plein rijdt een bezorger voorbij met drie broden die zachtjes snurken. Hij groet met zijn vrije oor. In de verte steekt de maanbloem boven de krater uit als een witte lantaarn. Daar moeten jullie zijn. Het stenen wandelpad buigt om de broodkarren heen. De rivier glijdt langs dezelfde kant van het plein. Mies legt haar houten lepel naast haar poot, bekijkt nog eens het gistkommetje en glimlacht. Er is geen haast. Een zorgvuldig meegenomen korreltje is straks veel nuttiger dan een volle zak die onderweg verloren gaat.\n\nWelke rustige route nemen jullie?`,
        choices: [c('Loop over de sterstenen', 'Volg het voetpad langs de broodbezorgers.', 'compass'), c('Vaar in de houten lepel', 'Dobber zachtjes langs de rand van het plein.', 'moon')],
      },
      {
        title: 'De mot met de volle snor',
        text: `${picks[1] === 0 ? 'De sterstenen geven onder je voeten een zacht tingelgeluid. Je wandelt samen met Mies tot aan de krater.' : 'De houten lepel dobbert als een wiegje. Mies stuurt met een andere lepel, tot jullie bij de krater aanleggen.'} Onder een maanbloem zit een ronde mot. Zijn snorren zitten vol glinsterende wensgist. ‘Ik kwam alleen even ruiken,’ mompelt hij. ‘Nu durf ik niet te bewegen, want dan kriebelt alles.’ De gist is nog prima, maar moet voorzichtig loskomen. Mies vindt een schone bloemenkwast in haar schortzak. De maanbloem heeft ook een breed, soepel blad dat als een waaier kan dienen. De mot houdt zijn vleugels stil. Op één snor balanceert een korreltje dat naar warme vanille ruikt, op de andere glanst een zachtblauw stofje.\n\nMies zegt vriendelijk gedag en vraagt of jullie dichterbij mogen komen. De mot knikt heel voorzichtig. Zijn snor trilt en een gouden korreltje maakt een piepklein sprongetje. Jij houdt het kommetje er alvast onder, zonder iets aan te raken. ‘Het is net of ik een nies in mijn snor heb,’ fluistert de mot. ‘Maar ik weet niet waar hij naartoe moet.’\n\nDe maanbloem buigt een beetje zodat jullie in haar schaduw staan. Op haar blad liggen witte dauwpareltjes die naar melk ruiken. Mies legt uit dat wensgist heel licht is. Een harde wind kan hem meenemen naar een verkeerde krater. Daarom blijven jullie dicht bij de mot en bewegen jullie rustig. Het kommetje staat stevig op een vlakke steen. De mot kijkt van het kwastje naar het bloemenblad. Allebei zien ze er vriendelijk uit. Hij wacht met zijn vleugels netjes over elkaar gevouwen op jullie voorstel.\n\nHoe helpen jullie de mot?`,
        choices: [c('Borstel de snorren voorzichtig', 'Vang de gist op in een schoon kommetje.', 'heart'), c('Maak een zacht bloemenbriesje', 'Waaier de korreltjes van zijn snorren af.', 'leaf')],
      },
      {
        title: 'Brood dat naar stilte luistert',
        text: `${picks[2] === 0 ? 'Met kleine veegjes borstel je de gist in het kommetje. De mot ontspant zijn snorren en bedankt je met een buiging.' : 'Je waaiert heel zacht met het bloemenblad. De gistkorrels dwarrelen het kommetje in. De mot kan weer rustig ademhalen.'} Terug in de bakkerij strooit Mies één korreltje over het deeg. Het beweegt! Maar wanneer de oven luid gaapt, zakt het weer in. ‘Dit brood wil rustig wakker worden,’ fluistert Mies. De oven kan zijn voetjes stilzetten als jullie samen een langzame maat aangeven. Je kunt zacht neuriën tijdens het kneden, of het deeg laten wiegen in een doek. Door het raampje kijken de eerste maanbewoners naar binnen. Mies gebaart dat ze nog even mogen wachten; zorgvuldig bakken kost gewoon een beetje tijd.\n\nDe oven trekt zijn deur op een klein kiertje en probeert een geluidloze gaap. Dat ziet er zo grappig uit dat Mies haar lach in haar schort verstopt. Jij voelt hoe de kom heel zacht onder de doek beweegt. Er gaat iets kleins op en neer, alsof het deeg wil ademhalen. Zodra iedereen even stil staat, wordt het een beetje ronder.\n\nMies vertelt dat maanbrood niet van een slaperig ontbijt houdt. Het wil wel wakker worden, alleen op zijn eigen rustige manier. Daarom leggen jullie drukke spullen opzij. De meelzeef hoeft nu niet te rammelen en het grote bakblik mag op een kussen staan. Buiten gaan de maanbewoners op de bank zitten. Eén van hen legt zijn lepel voorzichtig neer om te helpen. Jij kijkt naar de schone kneedplek en de zachte doek. Er is genoeg ruimte om samen uit te proberen welke beweging het brood prettig vindt.\n\nHoe maken jullie de bakkerij rustig?`,
        choices: [c('Neurie bij het kneden', 'Laat je handen een rustige melodie volgen.', 'music'), c('Wieg het deeg in een doek', 'Geef het brood een zachte schommelbeweging.', 'moon')],
      },
      {
        title: 'Een vorm voor het maanontbijt',
        text: `${picks[3] === 0 ? 'Op jouw zachte melodie kneedt Mies een langzame kring. De oven zet zijn voetjes stil en het deeg wordt luchtig.' : 'Jullie houden ieder een punt van de doek vast. Het deeg wiegt rustig heen en weer, tot het helemaal luchtig is.'} Een heerlijke geur vult de bakkerij. Het brood is klaar om een vorm te krijgen. Buiten wachten de maanbewoners met lege bordjes. Mies legt twee bakplaten neer. Op de ene past één grote broodmaan die jullie samen kunnen delen. Op de andere passen kleine broodjes die zelf zachtjes naar de ontbijtplekken kunnen hobbelen. ‘De gist heeft genoeg kracht voor allebei de plannen, ${hero}.’ Op iedere plaat ligt al een vel glad bakpapier klaar. Mies pakt haar ronde deegmes.\n\nMies geeft je een klein stukje deeg om te voelen. Het is zacht en veert langzaam terug wanneer je er met een vinger in duwt. Een afdrukje blijft heel even staan, als een klein maankratertje. ‘Dat is precies goed,’ zegt ze. De oven kijkt tevreden toe. Hij hoeft vandaag niet harder te gloeien, want de wensgist heeft zijn werk al gedaan.\n\nAan de andere kant van het raam wordt de tafel steeds langer. Er schuift een maanbewoner bij met een bord vol lege vakjes voor verschillende broodsmaken. Een bezorger zet een mand neer waarin straks ook kleine broodjes passen. Mies laat beide bakplaten zien. Bij het grote brood kan iedereen zelf een punt kiezen. Kleine wandelbroodjes kunnen juist bezoekjes brengen aan wie verder weg woont. Jij hoeft niet te raden welk plan mooier is. Jullie mogen kiezen welk soort ontbijt bij deze bijzondere ochtend past.\n\n‘Welke vorm zullen we maken?’`,
        choices: [c('Bak één grote broodmaan', 'Dek een lange tafel voor iedereen.', 'heart'), c('Maak wandelende broodjes', 'Laat het ontbijt zelf door het maanland reizen.', 'sparkles')],
      },
    ],
    ending: (picks, hero) => picks[4] === 0 ? {
      title: 'De tafel rond de maan',
      text: `De grote broodmaan komt goudgeel uit de oven. Mies snijdt zachte punten, terwijl jij buiten een lange tafel dekt. De mot brengt maanbloemen en de broodbezorgers schuiven hun manden onder de bank. Als iedereen een stukje heeft, klinkt de ontbijtbel helder over het plein. Zelfs de oven gaapt nu heel voorzichtig. Mies geeft ${hero} een klein, stevig sterbroodje als aandenken. Het hoeft niet opgegeten te worden: het is een bakkersster om de mooie ochtend mee te bewaren.\n\nEen kleine maanbewoner houdt zijn broodpunt eerst tegen het licht. In de luchtige binnenkant zitten gaatjes als piepkleine sterren. Hij kiest het hoekje met de grootste korst en vertelt dat dit precies zijn lievelingsstuk is. Mies legt naast ieder bord een bloemblad als servet.\n\nOp de bank schuift de mot zijn vleugels wat dichter tegen zich aan. Zijn snorren zijn weer schoon en hij kan eindelijk zonder kriebel aan het brood ruiken. Jij ziet hoe de bakkersster zacht oplicht in je hand. Hij is stevig genoeg om te bewaren, met een glad randje dat mooi onder je duim past. Door het ronde bakkersraam klinkt nog één tevreden zucht van de oven. Daarna begint iedereen rustig aan het ontbijt.`,
      keepsake: 'Een gouden bakkersster',
    } : picks[1] === 0 ? {
      title: 'De broodjes over het sterrenpad',
      text: `De broodjes krijgen kleine ronde voetjes. Ting, ting, ting! Over het pad van sterstenen huppelen ze naar de ontbijtplekken. Mies loopt voorop met een vlag van bakpapier. Ieder broodje stopt bij een leeg bord en maakt een diepe buiging. De maanbewoners vinden het zo grappig dat ze hun ontbijt bijna vergeten. Voor ${hero} blijft één piepklein belletje achter. Het zat aan Mies haar vlag en klinkt precies als de sterstenen waarop jullie samen naar de krater liepen.\n\nBij de kleinste maanwoning houden de broodjes even halt. De deur zit hoog, maar er staat al een leeg bord op een kruk. Eén broodje maakt een hupje en landt keurig midden op het bord. De bewoner applaudisseert met twee zachte klapjes, zodat de volgende broodjes hun pas niet kwijtraken.\n\nJij loopt nog een klein stukje mee en luistert naar het verschil tussen het pad en het belletje. De stenen klinken laag en rond; het belletje antwoordt licht en helder. Mies rolt haar vlag op wanneer de laatste mand leeg is. Op het plein wordt weer gewoon gewandeld. Als je jouw belletje heel zacht beweegt, hoor je toch nog hoe het ontbijt vandaag over de maan naar iedereen toe is gekomen.`,
      keepsake: 'Het belletje van de broodjesoptocht',
    } : {
      title: 'De ontbijtbootjes',
      text: `De kleine broodjes springen in schone houten lepels. Langs de rivier van maanlicht varen ze van huisje naar huisje. Mies zwaait bij iedere aanlegplek, terwijl de mot de lege lepels terugbrengt. Overal gaat een rond ontbijtluik open. De broodjes geven een zachte plof op de bordjes en de maan ruikt naar versgebakken korst. Mies maakt voor ${hero} een kleine lepelboot met een zeiltje van bakpapier. Je mag hem bewaren als herinnering aan jullie rustige reis.\n\nBij een klein huisje kijkt een slaperig gezicht uit het ontbijtluik. De bewoner heeft de bel wel gehoord, maar zijn deken wilde nog niet los. Nu ruikt hij het verse brood en schuift hij zijn bord met een glimlach naar buiten. Het bootje wacht geduldig tot hij klaar is om zijn broodje aan te pakken.\n\nJij volgt met je vinger de rand van jouw kleine lepelboot. Het zeiltje beweegt al bij een heel zacht zuchtje. Mies vertelt dat de grote lepels straks weer netjes teruggaan naar de bakkerij. De maanrivier wordt rustig en helder. Op de oevers verschijnen overal kruimeltjes op lege bordjes. Het ontbijt is aangekomen, en jullie mogen zelf ook nog een fijne warme plek aan tafel uitzoeken.`,
      keepsake: 'Een lepelbootje met een papieren zeil',
    },
    encounters: picks => picks.length ? [{ id: 'moonbakery-mies', name: 'Mies de maanbakker', fact: picks[0] === 0 ? 'Je vond in Mies haar receptenblik dat het maanbrood wensgist nodig had.' : 'Je hoorde samen met Mies dat het maanbrood om wensgist vroeg.' }, ...(picks.length >= 3 ? [{ id: 'moonbakery-mot', name: 'De maanmot', fact: picks[2] === 0 ? 'Je borstelde de wensgist voorzichtig van de snorren van de maanmot.' : 'Je waaierde de wensgist zachtjes van de snorren van de maanmot.' }] : [])] : [],
  },
  ocean: {
    threadLabel: 'Zoek met Tiko en Lumi het geluid van de koraaltuin terug.',
    scenes: (picks, hero) => [
      {
        title: 'De tuin die niet meer tingelde',
        text: `Op het strand vindt ${hero} een schelp die zachtjes klopt. Als je hem optilt, verschijnt een doorzichtige luchtbel om je heen. Je kunt er rustig in ademhalen terwijl hij onder water zakt. Daar wacht Tiko, een kleine zeeschildpad. ‘Onze koraaltuin is stil,’ zegt hij. ‘Normaal tingelen de klokbloemen wanneer het ochtend wordt.’ Tussen het roze koraal hangt zeepaardje Lumi aan een stengeltje. Ze laat een schelpenkaart zien. Een licht stroompje brengt water naar de klokbloemen, maar ergens onderweg blijft het hangen. Op het zand staan afdrukken. Ook zie je verderop een rij dansende luchtbelletjes.\n\nIn de luchtbel klinkt de zee heel anders dan op het strand. Je hoort kleine tikjes, zacht geritsel en af en toe een diepe plop. De bel beweegt vanzelf met het rustige water mee. Tiko zwemt naast je en laat met zijn voorpoot zien hoe je de bel zachtjes kunt laten draaien. Zo kunnen jullie samen goed kijken zonder het zand op te woelen.\n\nLumi rolt de schelpenkaart open. Er staan roze takjes op voor het koraal en blauwe bochten voor het water. Op één plek heeft ze een leeg rondje getekend: daar ontbreekt het vertrouwde ochtendgeluid. Een klokbloem dichtbij opent haar blaadjes, maar er komt alleen een heel klein zuchtje uit. Jij houdt je oor naar haar toe. Tiko luistert mee en knikt. Het stroompje moet ergens een omweg maken. Jullie gaan op onderzoek uit, terwijl de andere zeediertjes hun tuin rustig blijven verzorgen.\n\nWelk spoor wil je eerst volgen?`,
        choices: [c('Bekijk de afdrukken in het zand', 'Volg het spoor langs de zeebodem.', 'compass'), c('Zwem achter de luchtbelletjes aan', 'Kijk waar het stroompje nog wel beweegt.', 'sparkles')],
      },
      {
        title: 'Het zeewiergordijn',
        text: `${picks[0] === 0 ? 'De afdrukken lopen naar een rand van lange zeewierbladeren. Tiko zwemt laag boven het zand zodat niets wordt uitgewist.' : 'De belletjes dansen tot aan een rand van zeewier. Daar draaien ze steeds dezelfde kleine kring, zonder verder te komen.'} Achter het groene gordijn klinkt een zacht gefluit. Lumi herkent het: de kleine stroomvis zit erachter. Hij blaast normaal het ochtendwater naar de tuin. De bladeren zijn niet gevaarlijk, maar wel in elkaar gekronkeld. Jullie kunnen ze voorzichtig met schelpklemmetjes openhouden. Er zwemt ook een familie poetsgarnalen voorbij, die heel handig is met het ontwarren van dunne slierten. Lumi houdt haar schelpenkaart dicht tegen zich aan. Door een kier in het wier zie je een klein zilveren fluitje heen en weer bewegen.\n\nLumi houdt één blad opzij, maar het glijdt telkens weer terug. Het kietelt haar neus en ze moet niezen. Meteen buitelen er drie luchtbelletjes uit haar mond. Tiko wacht tot ze zijn opgestegen. ‘Er hoeft niets af,’ zegt hij over het wier. ‘We zoeken gewoon een manier waarop de bladeren hun eigen plekje weer krijgen.’\n\nDe poetsgarnalen blijven nieuwsgierig in de buurt. Hun dunne sprietjes bewegen alsof ze naar een onzichtbaar draadje zoeken. Op het zand liggen de lege schelpklemmetjes in een nette rij. Ze hebben gladde randen, precies breed genoeg om een blad vast te houden zonder erin te knijpen. Achter het gordijn klinkt weer dat kleine fluitje. Deze keer stopt het midden in een toon. Je roept dat jullie eraan komen. Er volgt een zacht, opgelucht tikje tegen een steen. De doorgang hoeft niet groot te worden: groot genoeg om elkaar goed te kunnen zien is al een fijn begin.\n\nHoe maken jullie een opening?`,
        choices: [c('Gebruik schelpklemmetjes', 'Houd de bladeren voorzichtig opzij.', 'compass'), c('Vraag de poetsgarnalen', 'Laat kleine helpers de slierten ontwarren.', 'heart')],
      },
      {
        title: 'Een vis met een verlegen fluit',
        text: `${picks[1] === 0 ? 'Je zet de schelpklemmetjes op de stevige bladranden. Zo blijft er een ruime, zachte doorgang open voor iedereen.' : 'De poetsgarnalen trekken ieder aan een los uiteinde. Even later hangt het zeewier als een nette groene boog boven jullie.'} In de opening zit een ronde stroomvis. Hij houdt een fluitje onder zijn vin. ‘Mijn nieuwe toon klinkt anders,’ zegt hij. ‘Misschien vinden de klokbloemen hem niet mooi.’ Lumi schudt haar kopje. Jullie hoeven niet te raden wat de bloemen vinden. Je kunt samen met de vis één proefnoot spelen, of eerst een klein klokbloempje hierheen laten meeluisteren. Tiko houdt de doorgang rustig vrij. Op de buik van de stroomvis glimt een rij blauwe stippen. Bij iedere ademhaling lichten ze even op, alsof de nieuwe melodie al voorzichtig naar buiten wil.\n\nDe stroomvis houdt zijn fluitje dicht tegen zich aan. Lumi zoekt een rustig plekje waar de kaart niet wegdrijft en gaat naast hem hangen. Tiko legt uit dat een nieuwe toon soms anders voelt in je eigen buik dan bij iemand die luistert. De vis knippert. Dat had hij nog niet bedacht. Hij blaast één stille adem uit, zonder al op zijn fluitje te spelen.\n\nJij ziet hoe een kleine klokbloem verderop haar blaadjes draait. Misschien is ze nieuwsgierig. Er staat een lege bloempot klaar die veilig in het zachte water kan meedrijven. Op de grond liggen ook open schelpen waar de wind van een bel een mooie toon uit kan halen. Jullie hebben dus twee manieren om klein te beginnen. De vis hoeft geen groot concert te geven. Hij mag eerst ontdekken hoe zijn nieuwe geluid samen met één ander geluid kan klinken, terwijl Tiko en Lumi gewoon dichtbij blijven.\n\nWat stel je voor?`,
        choices: [c('Speel samen één proefnoot', 'Maak een klein begin met een zacht schelpengeluid.', 'music'), c('Laat een klokbloempje luisteren', 'Breng een drijvende bloempot naar de stroomvis.', 'leaf')],
      },
      {
        title: 'Het water vindt zijn weg',
        text: `${picks[2] === 0 ? 'Je blaast zacht over een open schelp. De stroomvis speelt er één noot naast. Samen klinken ze als kabbelend water.' : 'Lumi brengt een klokbloempje in zijn drijvende pot. Op de nieuwe toon van de stroomvis opent het meteen zijn kleine kelk.'} De vis straalt en begint rustig te fluiten. Het ochtendwater beweegt weer, maar bij een zandheuveltje splitst het zich te breed. Er bereikt nog maar weinig stroom de tuin. Tiko wijst naar losse, gladde steentjes. Lumi vindt een lange holle schelp die als gootje kan dienen. Jullie kunnen het water om het heuveltje leiden of het door de schelp laten stromen. Het zandheuveltje is het huis van een slapende grondel. Die mag rustig blijven liggen; jullie nieuwe route past er met een ruime bocht omheen.\n\nJij volgt de dunne stroom met je ogen. Op sommige plekken bewegen de zandkorrels mee; verderop blijven ze stil liggen. De grondel heeft zijn neus onder een blaadje gestoken en snurkt in piepkleine stootjes. Bij iedere snurk verschijnt een belletje boven zijn huis. Niemand wil hem wakker maken voor een probleem dat ook met een ruime bocht opgelost kan worden.\n\nTiko zoekt de gladste stenen uit en legt ze naast elkaar op een lege plek. Lumi houdt de holle schelp tegen de kaart. De bocht van de schelp lijkt bijna op één van haar getekende waterroutes. Jullie bekijken waar de ingang en de uitgang zouden komen. De stroomvis speelt ondertussen zacht door, zodat je kunt zien hoe het water beweegt. Wat jullie straks bouwen, moet genoeg ruimte laten voor kleine zwemmers. Een vriendelijk pad voor het water kan tegelijk een fijne doorgang voor de tuinbewoners worden.\n\nWelke route maak je?`,
        choices: [c('Leg een slingerpad van stenen', 'Leid het water rustig langs het zandheuveltje.', 'compass'), c('Gebruik de holle schelp', 'Maak een klein watergootje richting de tuin.', 'sparkles')],
      },
      {
        title: 'Een melodie voor de tuin',
        text: `${picks[3] === 0 ? 'Tussen de gladde steentjes stroomt het water in een zachte slinger terug naar de koraaltuin.' : 'Het water glijdt door de holle schelp en maakt onderweg een mooi, laag zoemgeluid.'} De klokbloemen gaan één voor één open. Ting! Tong! Tingeling! De stroomvis hoort ze vanaf de zeewierboog en speelt vrolijk mee. Tiko laat een lege plek in de tuin zien. Daar kan een nieuw stukje koraal groeien dat het geluid bewaart. Je kunt er een kring van luisterplekjes maken voor bezoekers, of een kleine muziektoren die de melodie naar andere tuinen laat reizen. Lumi houdt het jonge koraalplantje voorzichtig vast.\n\nEen jonge vis steekt zijn kop tussen twee koraaltakjes door en luistert met een scheef oog. Daarna maakt hij zelf een piepklein tikgeluid met zijn vin. De klokbloemen antwoorden met een heldere toon. Lumi lacht. ‘Ze houden dus ook van nieuwe gasten.’ De tuin is niet langer één rij stille planten, maar een plek waar geluiden elkaar vinden.\n\nJij kijkt naar de lege ruimte. Er ligt zacht zand en er schijnt een brede strook licht door het water. Het jonge koraalplantje wiegt rustig in Lumi’s staart. Tiko haalt de grote schelpen weg die midden in het looppad lagen, zodat er plaats komt voor jullie plan. Een luisterkring zou bezoekers dicht bij het zachte getingel brengen. Een toren kan de melodie juist verder laten dragen. De stroomvis speelt beide mogelijkheden even voor: één toon heel dichtbij, daarna een toon die langzaam over de tuin glijdt.\n\nWat geef je de tuin erbij?`,
        choices: [c('Maak een kring om te luisteren', 'Geef iedereen een rustig plekje bij de bloemen.', 'heart'), c('Laat de melodie verder reizen', 'Bouw een vriendelijke koraalmuziektoren.', 'music')],
      },
    ],
    ending: (picks, hero) => picks[4] === 0 ? {
      title: 'De kring van luisterschelpen',
      text: `Rond het nieuwe koraalplantje leggen jullie schelpen als bankjes. Tiko maakt een ruime plek voor je luchtbel. Lumi nodigt de poetsgarnalen uit en de stroomvis speelt zijn nieuwe melodie. Niemand hoeft precies hetzelfde geluid te maken. Samen klinkt het alsof de hele zee zachtjes wakker wordt. Voordat ${hero} terug naar het strand zweeft, geeft Tiko je een kleine luisterschelp. Die bewaart geen stemmen of geheimen, maar wel het zachte ruisen van een heel fijne onderwaterdag.\n\nDe kleinste poetsgarnaal wil eerst alleen luisteren. Hij gaat achter een schelp zitten en laat zijn sprietjes op de maat bewegen. Even later schuift hij wat dichterbij. De kring heeft genoeg plaats; niemand hoeft zijn plekje af te staan. Tiko draait de grootste schelp een beetje zodat iedereen de bloemen goed kan zien.\n\nIn jouw luisterschelp zit een gladde groef die rond en rond loopt. Je volgt hem met je duim terwijl de luchtbel langzaam omhooggaat. Beneden wordt Lumi steeds kleiner, maar haar zwaaiende staart blijft lang zichtbaar tussen het koraal. Boven wacht het strand, met zacht zand onder je voeten. Als je de schelp even stil bij je houdt, denk je aan al die verschillende geluiden die samen een tuin lieten ontwaken.`,
      keepsake: 'Een kleine luisterschelp',
    } : picks[3] === 0 ? {
      title: 'Het lied langs de stenen',
      text: `Het jonge koraal groeit tot een torentje met open raampjes. De melodie stroomt erdoorheen en reist langs jullie stenenpad naar de volgende tuin. Ver weg antwoordt een tweede klokbloem. Daarna een derde! Lumi zwemt een vrolijk rondje om de toren, terwijl Tiko kijkt hoe de stille zeebodem langzaam weer vol geluid komt. Voor ${hero} vindt hij een glad steentje met een kringeltje erop. Het lag aan het begin van jullie waterpad en glanst als een kleine parel.\n\nEen klein schooltje vissen volgt het geluid tot aan het eerste raampje van de toren. Ze blijven ernaast zweven, zodat de melodie alle ruimte houdt. Het lied hoeft niet harder te worden om verder te reizen; het zachte stroompje neemt het vanzelf mee.\n\nJij strijkt over het kringeltje in het steentje. Aan de ene kant is het glad, aan de andere kant voel je een klein bobbeltje. Tiko laat zien waar het tussen de andere stenen lag. Daar loopt het water nu rustig doorheen. Wanneer jouw luchtbel naar boven begint te bewegen, blijven de klokbloemen elkaar antwoorden. Het steentje wordt een koele ronde herinnering in je hand. Langs de hele tuin klinkt nog een vriendelijk tingelen, steeds een beetje verder weg.`,
      keepsake: 'Een parelsteentje van het waterpad',
    } : {
      title: 'De schelp die verder zong',
      text: `Jullie zetten de muziektoren naast de holle schelp. De lage zoemtoon mengt zich met het heldere getingel van de bloemen. Het lied rolt als een vriendelijk golfje naar de tuinen verderop. De stroomvis steekt zijn vin omhoog: zijn nieuwe toon past er precies tussen. Lumi geeft ${hero} een klein leeg spiraalschelpje. Je mag het mee naar boven nemen, waar het droog en veilig in je hand rust. In de bocht lijkt nog een beetje gouden zeelicht te zitten.\n\nDe stroomvis probeert nog één keer alleen zijn nieuwe toon. Deze keer houdt hij zijn fluitje niet onder zijn vin verstopt. Het koraaltorentje neemt het geluid op en de holle schelp geeft er zijn lage zoemtoon bij. Lumi danst er met haar staart een langzaam kringetje omheen.\n\nJij kijkt door het kleine spiraalschelpje naar het licht van boven. Het gaatje maakt de zee tot een rond schilderijtje met een blauwe rand. Tiko begeleidt jouw luchtbel tot aan de eerste zonnestreep. Daar zwaait hij terug naar de tuin. Het schelpje is leeg en licht, maar in je hoofd klinkt het nieuwe lied nog even door. Op het strand leg je het voorzichtig naast je neer en voel je hoe warm de middagzon op je handen schijnt.`,
      keepsake: 'Een spiraalschelpje vol zeelicht',
    },
    encounters: picks => picks.length ? [{ id: 'ocean-tiko', name: 'Tiko de zeeschildpad', fact: picks[0] === 0 ? 'Je volgde met Tiko de afdrukken op weg naar de stille koraaltuin.' : 'Je volgde met Tiko de dansende luchtbelletjes bij de koraaltuin.' }, { id: 'ocean-lumi', name: 'Lumi het zeepaardje', fact: 'Lumi hielp je zoeken naar het verdwenen geluid van de koraaltuin.' }, ...(picks.length >= 3 ? [{ id: 'ocean-stroomvis', name: 'De stroomvis', fact: picks[2] === 0 ? 'Je speelde samen met de stroomvis een proefnoot op een schelp.' : 'Je liet een klokbloempje naar de nieuwe toon van de stroomvis luisteren.' }] : [])] : [],
  },
  garden: {
    threadLabel: 'Breng met Pip een dauwdruppel naar het kleine zaadje in de reuzentuin.',
    scenes: (picks, hero) => [
      {
        title: 'Een tuin boven je hoofd',
        text: `In een bloempot op de vensterbank ligt een opgevouwen laddertje. Zodra ${hero} het uitrolt, reikt het tot in een tuin vol reuzenbloemen. Onder een madelief zo groot als een parasol staat egel Pip. Zijn kruiwagen heeft een dopje als wiel. ‘Kijk eens hoe hoog alles groeit!’ zegt hij. ‘Maar één zaadje wil nog niet wakker worden.’ Midden in de tuin ligt een klein perkje onder een brede rabarberparaplu. Daar komt geen regen. Het zaadje heeft een druppel ochtenddauw nodig. Boven op een blad blinkt een druppel. In een andere hoek verzamelen slakken dauw in bloemblaadjes.\n\nPip geeft je een brede strohoed. Hij heeft er twee gaatjes in gemaakt waar zijn eigen oren nooit door pasten, maar bij jou zit de hoed prima. Als je omhoogkijkt, zie je een hommel die langs een bloem vliegt als een dikke, zachte luchtballon. Zijn gezoem laat de blaadjes heel even trillen. Het ruikt naar warme aarde en groene stengels.\n\nOnder de rabarberparaplu ligt het zaadje stil in zijn droge bedje. Pip heeft er een klein kringetje van steentjes omheen gelegd, zodat niemand per ongeluk door het perkje loopt. De grote bloemen krijgen overal water, maar hun brede bladeren houden juist de fijne druppels tegen die dit zaadje nodig heeft. Pip zet de kruiwagen naast je neer. Vandaag gaan jullie iets kleins bezorgen op een heel grote plek. Hij bekijkt de dauw boven op het blad en zwaait naar de slakken, die in de verte hun kommetjes aan het vullen zijn.\n\nWaar willen jullie eerst kijken?`,
        choices: [c('Klim naar de druppel op het blad', 'Volg het stevige laddertje tussen de stengels.', 'compass'), c('Bezoek de dauwslakken', 'Misschien hebben zij een druppel over.', 'heart')],
      },
      {
        title: 'Een kom voor een druppel',
        text: `${picks[0] === 0 ? 'Pip houdt het laddertje vast terwijl je naar het lage blad klimt. De dauwdruppel hangt precies binnen handbereik.' : 'De slakken begroeten jullie tussen natte viooltjes. Ze hebben genoeg dauw verzameld en schuiven graag één volle druppel naar voren.'} Alleen past de ronde druppel niet in Pips kruiwagen. Hij rolt er steeds weer uit en blijft dan bibberend op een blaadje liggen. Jullie moeten hem een zacht kommetje geven. Bij een zonnebloem liggen lege dopjes van zaden. Een brede tulp heeft een los bloemblaadje laten vallen dat je kunt vouwen. Pip heeft een draadje gras bij zich om iets vast te knopen. Op de druppel weerspiegelt de hele tuin ondersteboven. Pip ziet zijn eigen neus en moet zachtjes lachen. Een mosplukje houdt de kruiwagen ondertussen op zijn plek.\n\nPip haalt een meetlint van gevlochten gras uit zijn zak. Het heeft geen cijfers, maar kleine knoopjes. Hij legt het rond de druppel en daarna rond de lege plek in de kruiwagen. De druppel wiebelt even alsof hij het meetlint grappig vindt. ‘Hij heeft een beetje meer steun nodig dan ik dacht,’ zegt Pip.\n\nEen mierenbezorger komt langs met een piepklein pakje op zijn rug. Hij blijft even kijken en wijst naar de moskussens in de kar. Daar ligt ieder pakketje stevig tussen, ook als het een andere vorm heeft. Pip bedankt hem voor het meedenken. Jullie bekijken het harde zaaddopje en het zachte tulpenblad. De druppel hoeft nergens in geperst te worden. Het bakje moet zich juist om hem heen voegen. Jij legt het grasdraadje klaar en Pip controleert of zijn dopjeswiel nog netjes rond draait. Straks kan de kleine bezorgtocht echt beginnen.\n\nWat wordt jullie dauwkom?`,
        choices: [c('Gebruik een stevig zaaddopje', 'Een rond bakje dat in de kruiwagen past.', 'compass'), c('Vouw het tulpenblaadje', 'Een zachte kom met een grasstrik eromheen.', 'leaf')],
      },
      {
        title: 'De brug van het kevertje',
        text: `${picks[1] === 0 ? 'Het zaaddopje sluit mooi om de druppel. Pip zet het tussen twee moskussentjes in de kruiwagen.' : 'Je vouwt het tulpenblaadje omhoog en knoopt het gras eromheen. De druppel ligt rustig in het zachte kommetje.'} Op weg naar het perkje komen jullie bij een smal gootje. Daar bouwt een kevertje een brug van takjes. Er mist nog één dwarslat, dus de kruiwagen kan er niet overheen. Het kevertje wijst naar een gevallen veertje. Aan de andere kant ligt ook een breed blad waarmee jullie een klein veerbootje kunnen maken. Pip zet de kruiwagen stil, zodat de dauw niet klotst. Het gootje stroomt niet snel, maar de ronde druppel wil graag stil blijven liggen. Het kevertje haalt daarom ook een paar droge moskussentjes voor de oversteek.\n\nHet kevertje zet zijn gereedschap neer zodra hij de dauw ziet. ‘Voor een slokje leven maak ik graag plaats,’ zegt hij. Zijn brug bestaat uit takjes die precies in kleine inkepingen passen. Op de oever liggen nog twee stukjes gras, een plat steentje en het lichte veertje. Pip blijft met de kar op een stevig plekje staan.\n\nJij buigt om te kijken hoe breed het gootje is. Het water maakt een zacht kronkelgeluid langs een wortel. Aan de overkant beweegt het brede blad heel even mee met de stroom. Het kevertje kent iedere bocht van dit kleine stukje tuin. Hij kan straks helpen vasthouden, of eerst laten zien waar de brug het meeste steun nodig heeft. Jullie hoeven de dauw niet haastig te verplaatsen. Het mos houdt de kom koel en de druppel wacht rond en glanzend in zijn bedje, met de hele blauwe lucht erin weerspiegeld.\n\nHoe steken jullie over?`,
        choices: [c('Maak de takjesbrug af', 'Gebruik de stevige schacht van het veertje.', 'heart'), c('Maak een bladveerbootje', 'Vaar de dauw rustig naar de andere kant.', 'sparkles')],
      },
      {
        title: 'Een slaperig zaadje',
        text: `${picks[2] === 0 ? 'Het veertje wordt de laatste dwarslat. Het kevertje test de brug, en daarna rijdt Pip de kruiwagen voorzichtig naar de overkant.' : 'Het kevertje houdt een grastouw vast terwijl jullie bladbootje naar de overkant glijdt. De dauw blijft netjes in zijn kom.'} Eindelijk bereiken jullie het kleine perkje. Maar het zaadje ligt diep onder een harde kluit. Pip wil zijn stekels niet als hark gebruiken, want dat prikt zo onhandig. De grond moet zacht worden voordat de dauw erbij kan. Je ziet een vriendelijke worm bij een hoopje aarde. Naast het perkje staat een klein harkje van gevlochten gras. Pip rolt een gevallen bloemblaadje boven de dauwkom uit. Zo blijft de druppel koel terwijl jullie het bedje voor het kleine zaadje klaarmaken.\n\nPip gaat op zijn buik liggen om het perkje van dichtbij te bekijken. Er zit een klein barstje naast de harde kluit. Daaronder zie je donkere, zachte aarde. Het zaadje heeft dus al een fijn plekje, alleen de weg ernaartoe zit nog dicht. Jij zet het dauwkommetje neer op een vlak blad, ver genoeg van het randje.\n\nDe worm komt nieuwsgierig boven en groet met het puntje van zijn kop. Hij kent de grond van binnen en kan uitleggen waar de aarde het minst stevig is. Het grasharkje ligt juist klaar voor werk van bovenaf. Pip laat zien hoe zacht de gevlochten tandjes buigen. Daarmee kun je geen diepe kuil trekken, maar wel kleine kruimels losmaken. Het kevertje kijkt vanaf de rand mee en houdt zijn gereedschap stil. Voor dit klusje is ruimte belangrijker dan kracht. Jullie zoeken een weg waar de druppel straks vanzelf rustig naar beneden kan glijden.\n\nHoe maken jullie ruimte?`,
        choices: [c('Vraag de worm om een tunneltje', 'Maak van onderen een zacht weggetje naar het zaadje.', 'heart'), c('Werk met het grasharkje', 'Maak de bovenste grond heel voorzichtig los.', 'leaf')],
      },
      {
        title: 'Wat zal hier groeien?',
        text: `${picks[3] === 0 ? 'De worm graaft een klein tunneltje. De harde kluit zakt opzij en het zaadje krijgt een luchtig bedje.' : 'Met het grasharkje maak je kleine kringetjes. De harde kluit valt uiteen in zachte kruimels rond het zaadje.'} Nu schenken jullie samen de dauwdruppel uit. Meteen komt er een groene punt tevoorschijn. Hij groeit langzaam, zodat jullie goed kunnen kijken. ‘Dit is een luisterzaadje,’ zegt Pip. ‘Het groeit graag op een manier die bij zijn plek past.’ Onder de reuzenbloemen is ruimte voor een brede bladertent waar kleine bezoekers kunnen schuilen. Langs de kale muur past een bloementrap naar het zonlicht. Het groene puntje buigt naar jullie stemmen toe. De brede rabarberparaplu ritselt erboven, terwijl er een kleine warme zonnevlek op de losse aarde valt.\n\nHet puntje maakt een blaadje los dat nog opgevouwen zit als een groene envelop. Pip houdt zijn neus dichtbij en hoort een heel zacht kraakje. ‘Het opent zichzelf,’ fluistert hij. Je hoeft het blad niet uit elkaar te trekken. Samen kijken jullie hoe de rand langzaam naar buiten draait en een fijne schaduw op de aarde legt.\n\nPip zet zijn kruiwagen naast het nieuwe plantje neer. De kom is leeg, maar de ronde dauw lijkt nog heel even in het gladde bakje te glanzen. De slakken en het kevertje komen kijken naar wat jullie hebben gebracht. Er is nu een begin, en dat begin kan verschillende kanten op groeien. Jij kijkt eerst onder de hoge bloemen, waar een beschutte plek welkom zou zijn. Dan kijk je naar de zonnige rand boven aan de muur. Het luisterzaadje buigt telkens een beetje mee met jullie stemmen, alsof het beide plannen alvast probeert te begrijpen.\n\nWelke richting geven jullie het plantje?`,
        choices: [c('Laat een bladertent groeien', 'Maak een beschutte plek onder de grote bloemen.', 'heart'), c('Laat een bloementrap groeien', 'Verbind het perkje met de zonnige bovenrand.', 'sparkles')],
      },
    ],
    ending: (picks, hero) => picks[4] === 0 ? {
      title: 'Het huis onder de bladeren',
      text: `Twee brede bladeren buigen naar elkaar toe. Er ontstaat een ronde tent met een deur waar Pip precies doorheen past. Het kevertje brengt een takjesbankje, de slakken brengen een schaaltje dauw en de worm maakt de grond lekker zacht. Onder de hoge bloemen zit iedereen droog en koel. Pip schrijft geen bordje; hij hangt gewoon een open blad bij de ingang. Dat betekent welkom. Voor ${hero} rolt hij een klein bladkussentje op, vastgebonden met het grastouw van jullie reis.\n\nDe slakken parkeren hun huisjes naast de deur en kijken tevreden naar het bladerdak. Eén van hen ontdekt dat een regendruppel op het dak een heel mooi, zacht trommelgeluid maakt. Pip zet zijn kruiwagen onder de rand, waar hij morgen weer droog klaarstaat.\n\nJij probeert het bladbankje uit. Het wiegt een heel klein beetje mee en het ruikt naar verse groene bladeren. Door de open deur zie je de weg die jullie met de dauw hebben afgelegd. Zo groot leek die tuin toen jullie begonnen, en nu heeft hij ook een klein gezellig plekje. Pip helpt het bladkussentje voorzichtig in je handen leggen. Het grastouwtje zit stevig genoeg om het mee naar huis te nemen, zonder het zachte blad plat te drukken.`,
      keepsake: 'Een opgerold bladkussentje',
    } : picks[2] === 0 ? {
      title: 'De trap naar de zonnebloem',
      text: `Het plantje maakt brede, stevige blaadjes langs de muur. Samen vormen ze een trap naar het hart van de zonnebloem. Pip klimt mee tot het eerste rustplateau. Van daaruit zien jullie hoe klein het dauwkommetje beneden lijkt. Het kevertje bouwt een leuning van zachte twijgen, net zo zorgvuldig als zijn brug. Voor ${hero} vindt Pip een glad veerzaadje. Het lijkt op een piepkleine paraplu en draagt de herinnering aan jullie nieuwe weg door de reuzentuin.\n\nBij iedere trede ligt een blad net iets anders in het licht. Sommige zijn lichtgroen en dun, andere donker en stevig. Pip wijst een klein rustplekje aan waar jullie even kunnen zitten. De zonnebloem draait haar brede gezicht langzaam naar de middagzon.\n\nBeneden zwaaien de slakken bij het perkje. Het lege dauwkommetje glanst tussen de steentjes en herinnert aan die ene druppel waarmee alles begon. Jij houdt het veerzaadje tegen je hand. Het is zo licht dat het bijna op zijn eigen schaduw lijkt te rusten. Pip laat zien hoe je er een kommetje van je handen omheen maakt. Zo kan het mee naar huis zonder weg te waaien. Daarna dalen jullie rustig de bloementrap weer af, met tijd om op iedere trede iets nieuws te bekijken.`,
      keepsake: 'Een zacht veerzaadje',
    } : {
      title: 'Een tuin met een bovenverdieping',
      text: `De bloementrap groeit langs de muur en maakt halverwege een breed balkon. Daar kan zelfs Pips kruiwagen parkeren. De slakken brengen dauw naar boven en het kevertje legt beneden zijn bladbootje aan. Zo krijgt de tuin een waterroute én een wandelroute. Pip plukt geen bloem, maar raapt een leeg zaaddopje op van het balkon. Hij maakt er een klein mandje van voor ${hero}. Je kunt er later een gevonden blaadje of een mooie ronde kiezel in bewaren.\n\nVanaf het balkon kun je tegelijk het water en het nieuwe wandelpad zien. Het bladbootje ligt stil aan zijn grastouw. Bij het aanlegplekje rust een kevertje dat zijn gereedschap heeft opgeborgen. Iedereen kan nu kiezen hoe hij door de tuin wil reizen.\n\nPip maakt een klein gaatje in het hengsel van jouw mandje en legt uit dat er nog een grasdraadje door kan. Dan kun je het later ook ophangen. Jij kijkt of het ronde zaaddopje stevig in je hand ligt. Het is leeg, maar klaar voor een mooie vondst. Wanneer jullie beneden komen, staat de kruiwagen weer naast het perkje. Het luisterplantje ritselt boven jullie hoofd en laat een zacht vlekje schaduw op de plek vallen waar jullie afscheid nemen.`,
      keepsake: 'Een klein mandje van een zaaddop',
    },
    encounters: picks => picks.length ? [{ id: 'garden-pip', name: 'Pip de egel', fact: picks[0] === 0 ? 'Je zocht samen met Pip dauw op een groot blad voor het luisterzaadje.' : 'Je vroeg met Pip een dauwdruppel aan de slakken voor het luisterzaadje.' }, ...(picks.length >= 3 ? [{ id: 'garden-kever', name: 'Het bruggenkevertje', fact: picks[2] === 0 ? 'Je hielp het kevertje zijn takjesbrug af te maken met een veertje.' : 'Je stak met het kevertje het gootje over in een bladveerbootje.' }] : [])] : [],
  },
  clock: {
    threadLabel: 'Help Tik een rustige maat voor de grote boomklok te vinden.',
    scenes: (picks, hero) => [
      {
        title: 'Ontbijt vóór het wakker worden',
        text: `Ting! De boomklok slaat twaalf keer terwijl de zon nog maar net opkomt. ${hero} kijkt omhoog. In het deurtje onder de wijzerplaat staat muis Tik met een blauwe sjaal. ‘Hij loopt vooruit!’ roept hij. ‘De ontbijtbel klinkt vóór het ontbijt en mijn theewater fluit al voordat de ketel warm is.’ Via een brede wenteltrap klim je naar zijn werkplaats. Overal bewegen houten tandwielen. Tik heeft niets kapotgemaakt; de klok heeft vannacht een haastige windvlaag opgesnoven. Nu kent hij alleen nog maar snel. Op tafel ligt een routekaart van de raderen. Achter de muur hoor je een heel ongelijk getik.\n\nTik hangt zijn sjaal aan een haak en zet een klein krukje voor je neer. Vanuit het raam zie je dieren met lege ontbijtborden heen en weer lopen. Een konijn kijkt verbaasd naar een koude boterham. ‘De bel zei dat het al tijd was,’ roept hij. Tik steekt zijn poot op en belooft dat jullie gaan kijken wat er aan de hand is.\n\nIn de werkplaats hangt een geur van glad hout en bloementhee. Ieder tandwiel heeft een eigen vorm: brede tanden, kleine puntjes of een rand met ronde golfjes. Tik laat ze eerst veilig stoppen wanneer jullie dichtbij willen kijken. Je ziet niets dat gebroken is. De klok lijkt eerder buiten adem, alsof hij een heuvel op is gerend. Af en toe zucht er nog een windje door een kiertje. Op de werkbank wachten de raderkaart en twee luisterbekertjes. Jullie kunnen het haastige plekje vinden met goed kijken of goed luisteren.\n\nHoe begin je het onderzoek?`,
        choices: [c('Volg de routekaart van de raderen', 'Bekijk waar de beweging steeds sneller wordt.', 'compass'), c('Luister naar het ongelijke getik', 'Zoek met je oren het haastigste tandwiel.', 'music')],
      },
      {
        title: 'Het tandwiel met haast',
        text: `${picks[0] === 0 ? 'De pijlen op de kaart leiden naar een klein tandwiel boven de theekast. Daar begint alle beweging steeds sneller te worden.' : 'Tik, tik, tikketikketik! Je volgt het snelste geluid tot boven de theekast. Daar draait een klein tandwiel veel te vlug.'} Tik zet de klok even stil met een grote, ronde stopknop. In het tandwiel zit een haastveer, opgedraaid als een strakke krul. De veer hoeft niet weg. Hij moet alleen ruimte krijgen om langzaam uit te rollen. Jullie kunnen hem met twee houten spatels begeleiden. Tik heeft ook een zacht mosbakje waarin de veer vanzelf kan ontspannen. Op de werkbank tekent Tik eerst een ruime kring. Zo weet je hoe groot de ontspannen veer ongeveer hoort te zijn, zonder dat je hoeft te duwen.\n\nTik tekent naast de ruime kring een heel klein kringeltje. Zo ziet de veer er nu uit: veel te strak. Als hij met zijn vinger langs de tekening gaat, kun je bijna voelen hoe weinig plaats er over is. De klok staat ondertussen helemaal stil. Zelfs het kleine rad boven de deur wacht rustig op jullie.\n\nDe spatels hebben brede, gladde uiteinden. Tik legt ze naast elkaar om te laten zien hoe je daarmee samen steun kunt geven. Het mosbakje staat klaar als een zacht, groen nest. Er zit geen druppel water in, alleen een luchtig laagje mos waarop de veer zichzelf kan uitrekken. Jij kijkt naar het gespannen krulletje. Het hoeft niet weg en het hoeft nergens naartoe geduwd te worden. Jullie gaan het helpen weer ruimte te krijgen. Tik zet zijn gereedschapsdoos een stukje opzij, zodat er op de werkbank genoeg plek is voor het plan dat jij kiest.\n\nWelk plan voelt handig?`,
        choices: [c('Begeleid de veer met spatels', 'Rol hem samen voorzichtig en gelijkmatig uit.', 'compass'), c('Leg de veer in het mosbakje', 'Geef hem een zacht plekje om te ontspannen.', 'leaf')],
      },
      {
        title: 'Een klok zonder maat',
        text: `${picks[1] === 0 ? 'Jullie houden ieder een spatel vast. De haastveer rolt langzaam uit tot hij weer een ruime, soepele krul heeft.' : 'In het mosbakje rekt de haastveer zich uit. Hij zucht bijna hoorbaar en krijgt weer een ruime, soepele krul.'} Tik zet de veer terug en laat de stopknop los. De wijzers bewegen nu rustig, maar niet regelmatig: tik… taktak… tik. ‘We moeten hem een maat leren,’ zegt Tik. Buiten tikt een specht met zijn snavel op een lege boomtak. Beneden laat een oude waterpomp steeds één druppel in een emmer vallen. Allebei klinken ze regelmatig. Tik legt twee ronde luisterbekertjes klaar. ‘We hoeven geen geluid mee te nemen,’ legt hij uit. ‘Als we goed opletten, kunnen we de maat onthouden.’\n\nJij probeert zacht met je vinger mee te tikken op de rand van de tafel. Het is lastig als de klok telkens een stukje overslaat. Tik probeert het ook. Zijn snorren gaan scheef staan van het nadenken. Dan haalt hij diep adem en stopt met meetikken. ‘Eerst een goed voorbeeld zoeken,’ besluit hij. ‘Daarna kunnen we opnieuw beginnen.’\n\nDoor het open raam klinkt de specht duidelijk. Bij de waterpomp zie je iedere druppel eerst groeien, dan rond worden en tenslotte loslaten. Het zijn twee verschillende geluiden, maar allebei geven ze ruimte aan het volgende geluid. Tik doet de deur van zijn werkplaats open. De wenteltrap is breed genoeg om samen rustig af te dalen. De luisterbekertjes mogen gewoon op tafel blijven. Vandaag nemen jullie geen ding mee naar huis, maar een ritme dat je kunt onthouden door te luisteren, te knikken of zachtjes op je been te tikken.\n\nBij wie halen jullie een voorbeeld voor de klok?`,
        choices: [c('Luister naar de specht', 'Volg de rustige tikken op de holle tak.', 'music'), c('Luister naar de waterdruppels', 'Tel de zachte plonsjes in de emmer.', 'moon')],
      },
      {
        title: 'De bel die te vroeg wilde',
        text: `${picks[2] === 0 ? 'De specht tikt drie keer en wacht dan even. Tik neemt het ritme mee door zacht op zijn houten notitieplankje te kloppen.' : 'Plop, plop, plop. De waterdruppels vallen gelijkmatig. Tik onthoudt het ritme door rustig mee te knikken.'} In de werkplaats volgt het grote rad jullie voorbeeld. De wijzers lopen weer gelijk! Alleen de ontbijtbel zwiept al heen en weer voordat het juiste moment komt. Ze is gewend geraakt aan haast. Tik wil haar een seintje geven dat duidelijk zegt wanneer ze wél mag luiden. Jullie kunnen een houten wachtklepje maken, of een zacht koord met een belsignaal aan de juiste wijzer vastmaken. De bel zelf vindt beide plannen fijn. ‘Ik wil best wachten,’ zegt ze, ‘als ik maar weet wanneer mijn geluid aan de beurt is.’\n\nDe bel hangt aan een houten balkje met een klein rond raampje ernaast. Vanaf die plek kan ze het dorpsplein zien. Elke keer als er iemand met een bord voorbijloopt, wil ze alvast helpen door te luiden. ‘Ik dacht dat vroeg beginnen altijd handig was,’ vertelt ze. Beneden gaat juist een deur open omdat iemand nog zijn ontbijt moet pakken.\n\nTik zet de beweging weer even veilig stil, zodat jullie het balkje kunnen bekijken. Hij wijst aan waar een klepje kan schuiven zonder ergens tussen te knellen. Aan de andere kant zit een glad oogje waar een zacht koord doorheen past. Allebei kunnen ze de bel een duidelijk moment geven. Jij houdt één houten onderdeel omhoog en daarna een stukje koord. De bel maakt geen geluid, maar zwaait heel klein als teken dat ze oplet. Het grote rad wacht geduldig op het seintje dat jullie samen gaan bedenken.\n\nWat bouw je?`,
        choices: [c('Maak een houten wachtklepje', 'Laat de bel pas los als het rad goed staat.', 'compass'), c('Maak een koord met een seintje', 'Geef de bel op het juiste moment een zachte trek.', 'heart')],
      },
      {
        title: 'Tijd voor een rustig begin',
        text: `${picks[3] === 0 ? 'Het klepje houdt de bel even tegen. Pas wanneer het juiste tandje voorbijkomt, schuift het opzij: ting!' : 'Het koord beweegt mee met de juiste wijzer. Op het goede moment geeft het de bel één zachte trek: ting!'} Beneden zetten de dieren hun ontbijt klaar. Deze keer klinkt de bel precies wanneer de kommen op tafel staan. Tik doet zijn blauwe sjaal weer netjes om. ‘Nu wil ik iets maken dat ons helpt rustig te beginnen, ${hero}.’ In de klok is ruimte voor een klein ochtendmuziekje. Buiten past een bankje waar iedereen even kan wachten tot zijn eigen plan aan de beurt is. Op de werkbank liggen nog wat gladde plankjes en drie ronde klankstaafjes over. Tik wacht geduldig op jouw idee, zonder alvast te gaan timmeren.\n\nJij luistert nog even naar de boomklok. Er zit nu ruimte tussen tik en tak, precies genoeg om ook de vogels te horen. Beneden wordt de thee ingeschonken zonder dat iemand naar een te vroege bel hoeft te rennen. Een muisje zwaait met een lepel en gaat daarna rustig weer zitten. Tik kijkt tevreden door het ronde raam.\n\nHij legt de plankjes en klankstaafjes op een doek. Het ochtendmuziekje zou klein kunnen blijven: een paar tonen, dan weer stilte. Een bankje buiten geeft juist een plekje aan wie even wil zitten voordat hij verdergaat. Jij mag de gladde materialen voelen en bedenken hoe de dieren ze zouden gebruiken. Tik pakt pas een potlood wanneer jij klaar bent met kijken. De klok tikt ondertussen door, zonder jullie op te jagen. Er is tijd om iets te maken dat morgen, overmorgen en op nog veel meer ochtenden prettig blijft.\n\nWat voegen jullie toe?`,
        choices: [c('Een zacht ochtendmuziekje', 'Laat de dag met een korte melodie beginnen.', 'music'), c('Een wachtbankje bij de boom', 'Maak een fijne plek voor een klein rustig moment.', 'leaf')],
      },
    ],
    ending: (picks, hero) => picks[4] === 0 ? {
      title: 'De melodie van precies op tijd',
      text: `Tik maakt drie houten klankstaafjes vast aan het grote rad. Iedere ochtend spelen ze een kort, rustig liedje voordat de ontbijtbel klinkt. De specht luistert vanaf zijn tak en de waterpomp drupt zachtjes mee. Na het lied is het weer stil genoeg om elkaar te horen. Tik zet twee stoeltjes bij zijn werkbank en schenkt warme bloementhee in. Voor ${hero} heeft hij een klein houten klokhangertje gemaakt. Er staan geen cijfers op, maar een zon, een bankje en een mooie ronde maan.\n\nHet eerste liedje klinkt zacht genoeg om de kleinste muis niet te laten schrikken. Ze doet haar raam open, rekt zich uit en zwaait naar de boom. Daarna klinkt de bel. Op het plein schuiven de dieren hun stoelen rustig naar de ontbijttafel.\n\nJij bekijkt het hangertje van dichtbij. Tik heeft de rand glad gemaakt, zodat nergens een splinter zit. Bij de getekende zon voel je een klein rond kuiltje. Het bankje ligt ernaast, alsof je er in gedachten even op kunt gaan zitten. Tik ruimt de laatste houtkrullen van zijn werkbank en bergt zijn gereedschap op. De boomklok tikt regelmatig verder. Jullie thee hoeft niet snel op. Er is nog tijd om samen naar het kleine muziekwerk te kijken terwijl het langzaam een volgende ronde begint.`,
      keepsake: 'Een houten klokhangertje',
    } : picks[2] === 0 ? {
      title: 'Het bankje onder de spechtenboom',
      text: `Jullie zetten een bankje onder de tak van de specht. Wie te vroeg is voor een afspraak, kan er even zitten en naar het rustige tikken luisteren. Tik hangt zijn routekaart in het klokdeurtje, zodat hij later nog weet hoe jullie de haast hebben gevonden. ${hero} krijgt een klein houten notitieplankje mee, met drie stippen en een pauze ertussen. Het is hetzelfde ritme dat de klok hielp. De ontbijtbel klinkt nog eenmaal, precies op tijd voor een tweede kopje thee.\n\nDe specht probeert het ritme van het plankje na te doen. Daarna wacht hij netjes, zodat jij kunt antwoorden. Tik lacht: zijn nieuwe wachtbankje heeft meteen een eerste spel gekregen. Een eekhoorn gaat op de andere kant zitten en luistert zonder iets te zeggen.\n\nOp de achterkant van jouw notitieplankje heeft Tik een klein blaadje getekend. Dat herinnert aan de boom waarin jullie samen werkten. Je houdt het plankje op je schoot en tikt de drie stippen na. Na de laatste stip is er even niets. Juist in dat kleine stille stukje hoor je hoe de wind door de bladeren gaat. De klok loopt door, de specht wacht op zijn tak en niemand hoeft jullie spel haastig af te maken. Tik schenkt nog een klein beetje thee bij.`,
      keepsake: 'Een ritmeplankje met drie stippen',
    } : {
      title: 'Het bankje bij de druppelpomp',
      text: `Het nieuwe bankje komt naast de oude waterpomp. Onder de emmer hangt Tik een klein schaaltje, zodat de druppels er helder in klinken. Wie wacht, kan rustig luisteren naar plop, plop, plop. De klok hoeft nergens meer heen te rennen. Hij mag gewoon ieder moment op zijn beurt laten komen. Voor ${hero} knoopt Tik een glad, blauw kraaltje aan een draad. Het lijkt op een waterdruppel en herinnert je aan het zachte geluid dat jullie samen hebben gevonden.\n\nEen jong konijn komt bij het bankje staan met een mandje op zijn arm. Hij is wat vroeg voor de markt, maar vindt dat ineens helemaal niet erg. Hij zet zijn mand naast zich neer en telt samen met jullie drie heldere plonsjes. Daarna luistert hij gewoon verder zonder te tellen.\n\nJij legt het blauwe kraaltje op je hand. Binnenin lijkt een dun streepje licht te zweven. Tik maakt het knoopje van de draad nog een keer zorgvuldig vast. Het kraaltje kan straks veilig in je jaszak of aan een klein haakje thuis. Wanneer je opstaat, hoor je de boomklok en de waterpomp tegelijk. Het zijn twee verschillende geluiden, die ieder hun eigen rustige plekje hebben gekregen. Tik zwaait bij de wenteltrap terwijl jullie afscheid nemen.`,
      keepsake: 'Een blauw druppelkraaltje',
    },
    encounters: picks => picks.length ? [{ id: 'clock-tik', name: 'Tik de klokmuis', fact: picks[0] === 0 ? 'Je volgde met Tik de raderkaart om het haastige tandwiel te vinden.' : 'Je vond met Tik het haastige tandwiel door naar het getik te luisteren.' }, ...(picks.length >= 3 && picks[2] === 0 ? [{ id: 'clock-specht', name: 'De rustige specht', fact: 'Je luisterde naar het regelmatige ritme van de specht voor de boomklok.' }] : [])] : [],
  },
};
